css:
/* Winamp Classic: original CSS, no proprietary player assets. */
[data-skin-part="shell"] { background: #181923; gap: 4px; padding: 4px; }
[data-skin-part="navigation"], [data-skin-part="sidebar"], [data-skin-part="main"] { border: 2px solid; border-color: #777b8c #080911 #080911 #777b8c; box-shadow: inset 1px 1px #a0a2ad, inset -1px -1px #3c3e4c; }
[data-skin-part="navigation"], .side__head, .thread__foot { background: url("skin:metal"); }
[data-skin-part="header"], .side__heading { background: linear-gradient(90deg, #242333, #57576e 48%, #242333); border-bottom: 2px groove #9295a3; color: #f4f1db; text-shadow: 1px 1px #080912; }
.pane-head__title, .side__title { font-family: var(--font-mono); text-transform: uppercase; letter-spacing: 0.08em; font-weight: 700; }
.side__heading { padding: 6px; }
.side__search, [data-skin-part="composer"], .field { border: 2px solid; border-color: #080b08 #676d61 #676d61 #080b08; box-shadow: inset 1px 1px #000000; background: #10130f; }
.side__search-input, .composer__input { color: #b9f66a; font-family: var(--font-mono); }
[data-skin-part="conversation"], [data-skin-part="welcome"] { background: radial-gradient(ellipse at top, #282b36, #12151b); }
[data-skin-part="message"][data-role="assistant"] .bubble { background: #111810; border: 1px solid #505a42; border-left: 3px solid #8cc633; padding: 14px; box-shadow: inset 0 0 18px #000000; }
[data-skin-part="message"][data-role="user"] .bubble { border: 1px solid #7c9255; box-shadow: 2px 2px #050705; }
.bubble__body pre, [data-skin-part="code"] { border: 2px inset #5d6651; background: #090d08; }
.btn, .pick, .rail__item { border: 1px solid; border-color: #9294a2 #070811 #070811 #9294a2; background: linear-gradient(#555867, #353746 50%, #272938 51%, #3e4050); color: #efefdd; box-shadow: inset 1px 1px #6d6f7c; border-radius: 2px; }
.btn:hover, .pick:hover, .rail__item:hover { background: linear-gradient(#666a7a, #353948); color: #c6ff6f; }
.btn--primary, .rail__item--active { color: #c6ff6f; background: linear-gradient(#3c4d25, #17230e); border-color: #8f9d79 #060b03 #060b03 #8f9d79; }
.composer__send::before { clip-path: none; border: 2px outset #b5d877; background: linear-gradient(#bfed72, #6f9f32); }
.composer__send:disabled::before { background: #3c4436; border-color: #69745e; }
.rail__brand .brand-mark { color: #b4f83f; filter: drop-shadow(0 0 3px #71ad1b); }
.row-item--active { background: #132007; border-left: 3px solid #a8ef38; }
.row-item--active .row-item__title { color: #c6ff6f; font-family: var(--font-mono); }
.chip { border-radius: 1px; border: 1px solid #646956; font-family: var(--font-mono); text-transform: uppercase; }
.settings__title, .welcome__title { font-family: var(--font-mono); letter-spacing: 0.04em; }
@media (min-width: 901px) { [data-skin-part="shell"] { padding: 10px; gap: 8px; } }
@media (max-width: 900px) { [data-skin-part="shell"] { gap: 0; padding: 0; } [data-skin-part="header"] { border-top: 2px groove #9295a3; } }
